#include <algorithm>
#include <iostream>
#include <string>
using namespace std;

int main() {
    string ans, guess, row;
    for (int i = 0; i < 3; i++) { cin >> row; ans += row; }
    for (int i = 0; i < 3; i++) { cin >> row; guess += row; }
    int green = 0, ansCnt[26] = {}, guessCnt[26] = {};
    for (int i = 0; i < 9; i++) {
        if (ans[i] == guess[i]) {
            green++;
        } else {
            ansCnt[ans[i] - 'A']++;
            guessCnt[guess[i] - 'A']++;
        }
    }
    int yellow = 0;
    for (int c = 0; c < 26; c++) yellow += min(ansCnt[c], guessCnt[c]);
    cout << green << '\n' << yellow << '\n';
    return 0;
}

