import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        StringBuilder ans = new StringBuilder();
        StringBuilder guess = new StringBuilder();
        for (int i = 0; i < 3; i++) ans.append(sc.next());
        for (int i = 0; i < 3; i++) guess.append(sc.next());
        int green = 0;
        int[] ansCnt = new int[26];
        int[] guessCnt = new int[26];
        for (int i = 0; i < 9; i++) {
            char a = ans.charAt(i), g = guess.charAt(i);
            if (a == g) green++;
            else {
                ansCnt[a - 'A']++;
                guessCnt[g - 'A']++;
            }
        }
        int yellow = 0;
        for (int c = 0; c < 26; c++) yellow += Math.min(ansCnt[c], guessCnt[c]);
        System.out.println(green);
        System.out.println(yellow);
    }
}

